@js:
eval(String(source.loginUrl));
java.toast("【设置信息】\n域名"+v+":"+Nam+"/"+burl);

sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url=url!=null?burl+url:"",
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	push("分类", null, 1, 1);
	fl=["男频","女频","中国文学","外国文学","轻小说","百合","耽美","网盘资源"];
fl.map((title,index)=>{
	index++;
	url= `/sort/${index}_{{page}}/`;
	if(index+1 <= fl.length - fl.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}  	
    })

push("完本",  `/full/{{page}}/`, 1, 1);

 push("榜单", null, 1, 1);
 bd = [["总点击","allvisit"],["月点击","monthvisit"],["周点击","weekvisit"],["日点击","dayvisit"],["总推荐","allvote"],["字数","size"],["入库","postdate"],["最近","lastupdate"]];
	  bd.map(([title,uri],index)=>{
	    url= `/top/${uri}_{{page}}/`;
	if(index+1 <= bd.length - bd.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}	
    	});
JSON.stringify(sort);

