source.loginUrl:
BurlList=[
["霹雳书坊","https://www.pilibook.net"],
["霹雳书屋","https://www.pilisf.com"],
["春雨书屋","https://www.chunyushuwu.com"],
["夏日书屋","https://www.xiarishuwu.com"],
["秋风书屋","https://www.qiufengshuwu.com"],
["冬雪书屋","https://www.dongxueshuwu.com"]];

var v=source.getVariable();
	if(v==null||v==""){
		burl = BurlList[0],Nam=burl[0],burl=burl[1];
		java.toast("\n❗未设置❗\n默认启用："+Nam+"/"+burl);
		//默认启用
		source.setVariable("0");
	}
else{
	var v = v.match(/\d+$/)[0];
 burl = BurlList[v],Nam=burl[0],burl=burl[1];
}

//设置注意事项
function log(t){
		java.longToast('【设置注意事项】\n\n\n  ㈠ 请点击下方按键进行相应设置\n  ㈡ 设置后请刷新\n')
	}

// 获取域名接口信息
function get(n){	  
	burl=BurlList[n];
	java.toast('【域名接口信息】\n\n\n　　当前接口：'+burl[0]+":"+burl[1]);
}	

//设置域名接口
function ym(i){
	burl=BurlList[i];
	java.toast('【设置成功提示】\n\n\n　　已选择【'+burl[0]+":"+burl[1]+'】为当前接口');
	return source.setVariable(i)
	}

